-- WP9-009 local accounts (owner decision 2026-11-10: "akun lokal di aplikasi dahulu").
-- Replaces the Oracle APEX workspace accounts for the target. APEX password hashes cannot be exported, so every
-- account starts with a temporary password that must be changed at first login.
-- Schema iam is separate from schema app (the converted source schema) and survives a re-creation of app:
-- accounts are not part of the APEX data snapshot. Hand-written, reviewed migration (not generated by the plan).

CREATE SCHEMA IF NOT EXISTS iam;

CREATE TABLE IF NOT EXISTS iam.accounts (
    username             varchar(255) PRIMARY KEY,
    password_hash        text         NOT NULL,
    must_change_password boolean      NOT NULL DEFAULT true,
    active               boolean      NOT NULL DEFAULT true,
    failed_attempts      integer      NOT NULL DEFAULT 0,
    locked_until         timestamptz,
    session_version      integer      NOT NULL DEFAULT 1,
    password_changed_at  timestamptz  NOT NULL DEFAULT now(),
    last_login_at        timestamptz,
    created_by           varchar(255) NOT NULL,
    created_at           timestamptz  NOT NULL DEFAULT now(),
    updated_by           varchar(255) NOT NULL,
    updated_at           timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT accounts_username_ck CHECK (username = upper(btrim(username)) AND username <> ''),
    CONSTRAINT accounts_hash_ck CHECK (password_hash LIKE 'scrypt$%'),
    CONSTRAINT accounts_failed_ck CHECK (failed_attempts >= 0),
    CONSTRAINT accounts_version_ck CHECK (session_version >= 1)
);

-- Audit trail of security events (never contains passwords).
CREATE TABLE IF NOT EXISTS iam.account_events (
    event_id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    username   varchar(255) NOT NULL,
    event      varchar(30)  NOT NULL,
    actor      varchar(255) NOT NULL,
    at         timestamptz  NOT NULL DEFAULT now(),
    detail     varchar(200),
    CONSTRAINT account_events_event_ck CHECK (event IN ('CREATED', 'LOGIN_OK', 'LOGIN_FAILED', 'LOCKED', 'UNLOCKED',
        'PASSWORD_CHANGED', 'PASSWORD_RESET', 'LOGOUT', 'SESSIONS_REVOKED', 'DEACTIVATED', 'ACTIVATED'))
);
CREATE INDEX IF NOT EXISTS account_events_user_ix ON iam.account_events (username, at);
